function CalendarContextMenu({ c, menu, items, onClose }) {
  const menuRef = useRef(null);
  const [position, setPosition] = useState({ left: 8, top: 8, ready: false });
  const visibleItems = items.filter(Boolean);
  const menuKey = menu ? `${menu.x}:${menu.y}:${visibleItems.length}` : "";

  useEffect(() => {
    if (!menu) return undefined;
    let frame = 0;
    let secondFrame = 0;

    function placeAtCursor() {
      const element = menuRef.current;
      if (!element) return;
      const gap = 8;
      const margin = 8;
      const rect = element.getBoundingClientRect();
      const width = rect.width || 224;
      const height = rect.height || 40;
      let left = menu.x + gap;
      let top = menu.y + gap;
      if (left + width > window.innerWidth - margin) left = menu.x - width - gap;
      if (top + height > window.innerHeight - margin) top = menu.y - height - gap;
      left = Math.max(margin, Math.min(left, window.innerWidth - width - margin));
      top = Math.max(margin, Math.min(top, window.innerHeight - height - margin));
      setPosition({ left, top, ready: true });
    }

    function schedulePlacement() {
      window.cancelAnimationFrame(frame);
      frame = window.requestAnimationFrame(() => {
        placeAtCursor();
        secondFrame = window.requestAnimationFrame(placeAtCursor);
      });
    }

    function handlePointer(event) {
      if (!menuRef.current?.contains(event.target)) onClose();
    }
    function handleKey(event) {
      if (event.key === "Escape") onClose();
    }

    setPosition({ left: menu.x, top: menu.y, ready: false });
    schedulePlacement();
    window.addEventListener("resize", schedulePlacement);
    window.visualViewport?.addEventListener("resize", schedulePlacement);
    window.addEventListener("pointerdown", handlePointer);
    window.addEventListener("keydown", handleKey);
    return () => {
      window.cancelAnimationFrame(frame);
      window.cancelAnimationFrame(secondFrame);
      window.removeEventListener("resize", schedulePlacement);
      window.visualViewport?.removeEventListener("resize", schedulePlacement);
      window.removeEventListener("pointerdown", handlePointer);
      window.removeEventListener("keydown", handleKey);
    };
  }, [menuKey]);

  if (!menu || typeof document === "undefined") return null;
  const menuNode = (
    <div
      ref={menuRef}
      className="calendar-context-menu"
      style={{ left: position.left, top: position.top, width: 224, visibility: position.ready ? "visible" : "hidden" }}
      role="menu"
    >
      {visibleItems.map((item, index) => item.separator ? (
        <span key={`separator-${index}`} className="calendar-context-separator" />
      ) : (
        <button
          key={item.id || item.label}
          type="button"
          className="calendar-context-item"
          data-danger={item.danger ? "true" : "false"}
          disabled={item.disabled}
          onClick={() => { item.action?.(); onClose(); }}
          role="menuitem"
        >
          <Icon name={item.icon || "calendar"} size={14} />
          <span>{item.label}</span>
          {item.hint && <small>{item.hint}</small>}
        </button>
      ))}
    </div>
  );
  return createPortal(menuNode, document.body);
}

function WeekCalendar({
  c,
  events,
  weekStart,
  daysCount = 7,
  onMoveEvent,
  onSlotClick,
  onEventClick,
  onContextRequest,
  onStartReview,
  weekdayLabels,
  density = "compact",
  viewportMode = "workspace",
  onResizeEvent,
  onRangeCreate,
  selectedEventId = null,
  initialScrollMinutes = null,
}) {
  const days = Array.from({ length: daysCount }, (_, index) => addDays(weekStart, index));
  const dateStrings = days.map((day) => dateKey(day.getFullYear(), day.getMonth(), day.getDate()));
  const [dragId, setDragId] = useState(null);
  const [hoverDay, setHoverDay] = useState(null);
  const [resizePreview, setResizePreview] = useState(null);
  const [createPreview, setCreatePreview] = useState(null);
  const scrollRef = useRef(null);
  const scrollSaveTimerRef = useRef(null);
  const touchMovedRef = useRef(null);
  const createDragRef = useRef(null);
  const suppressSlotClickRef = useRef(false);
  const programmaticScrollRef = useRef(false);
  const userScrolledRef = useRef(false);
  const scrollStorageKey = `medlearn-calendar-scroll-${viewportMode}-${daysCount}`;
  const startHour = 0;
  const endHour = 24;
  const hourHeight = CALENDAR_DENSITY_HEIGHT[density] || CALENDAR_DENSITY_HEIGHT.compact;
  const totalHeight = (endHour - startHour) * hourHeight;
  const today = new Date();
  const todayString = dateKey(today.getFullYear(), today.getMonth(), today.getDate());
  const nowMinutes = today.getHours() * 60 + today.getMinutes();
  const nowTop = (nowMinutes / 60) * hourHeight;

  const scrollInitializationKey = `${viewportMode}:${daysCount}:${dateStrings.join(",")}:${density}:${Number.isFinite(initialScrollMinutes) ? initialScrollMinutes : "auto"}`;

  useEffect(() => {
    const root = scrollRef.current;
    if (!root) return undefined;
    let cancelled = false;
    let frame = 0;
    let releaseFrame = 0;
    let retryTimer = 0;
    let settleTimer = 0;
    let lateTimer = 0;
    let observer = null;
    let attempts = 0;
    userScrolledRef.current = false;

    const hasFixedTarget = Number.isFinite(initialScrollMinutes);
    const stored = hasFixedTarget ? Number.NaN : Number(sessionStorage.getItem(scrollStorageKey));
    const targetMinutes = hasFixedTarget
      ? initialScrollMinutes
      : calendarScrollTargetMinutes(events, dateStrings, new Date());
    const targetTop = Number.isFinite(stored) && stored >= 0
      ? stored
      : Math.max(0, (targetMinutes / 60) * hourHeight);

    function applyInitialScroll() {
      if (cancelled || userScrolledRef.current || !scrollRef.current) return;
      const element = scrollRef.current;
      if (hasFixedTarget) {
        element.style.setProperty("--calendar-initial-scroll-tail", "0px");
        const baseScrollHeight = element.scrollHeight;
        const requiredTail = Math.max(0, Math.ceil(targetTop + element.clientHeight - baseScrollHeight + 1));
        element.style.setProperty("--calendar-initial-scroll-tail", `${requiredTail}px`);
      }
      const maxScroll = Math.max(0, element.scrollHeight - element.clientHeight);
      if (maxScroll <= 0) {
        if (attempts < 12) retryTimer = window.setTimeout(scheduleInitialScroll, 40);
        return;
      }
      programmaticScrollRef.current = true;
      element.scrollTop = Math.min(maxScroll, targetTop);
      window.cancelAnimationFrame(releaseFrame);
      releaseFrame = window.requestAnimationFrame(() => { programmaticScrollRef.current = false; });
    }

    function scheduleInitialScroll() {
      window.cancelAnimationFrame(frame);
      frame = window.requestAnimationFrame(() => {
        attempts += 1;
        applyInitialScroll();
      });
    }

    scheduleInitialScroll();
    settleTimer = window.setTimeout(scheduleInitialScroll, 120);
    lateTimer = window.setTimeout(scheduleInitialScroll, 320);
    if (typeof ResizeObserver !== "undefined") {
      observer = new ResizeObserver(() => {
        if (!userScrolledRef.current) scheduleInitialScroll();
      });
      observer.observe(root);
    }

    return () => {
      cancelled = true;
      window.cancelAnimationFrame(frame);
      window.cancelAnimationFrame(releaseFrame);
      window.clearTimeout(retryTimer);
      window.clearTimeout(settleTimer);
      window.clearTimeout(lateTimer);
      observer?.disconnect();
      root.style.removeProperty("--calendar-initial-scroll-tail");
      programmaticScrollRef.current = false;
    };
  }, [scrollInitializationKey, hourHeight, scrollStorageKey]);

  function rememberScrollPosition(domEvent) {
    if (programmaticScrollRef.current) return;
    userScrolledRef.current = true;
    window.clearTimeout(scrollSaveTimerRef.current);
    const top = domEvent.currentTarget.scrollTop;
    scrollSaveTimerRef.current = window.setTimeout(() => sessionStorage.setItem(scrollStorageKey, String(top)), 120);
  }

  function layoutEvents(dayEvents) {
    const items = dayEvents
      .filter((event) => event.time && !event.allDay)
      .map((event) => {
        const start = timeToMinutes(event.time) || 0;
        const previewEnd = resizePreview?.id === event.id ? resizePreview.endMinutes : null;
        return { event, start, end: previewEnd ?? start + calendarDurationMinutes(event), lane: 0, laneCount: 1 };
      })
      .sort((a, b) => a.start - b.start || b.end - a.end);
    const groups = [];
    let activeGroup = [];
    let groupEnd = -1;
    items.forEach((item) => {
      if (activeGroup.length && item.start >= groupEnd) {
        groups.push(activeGroup);
        activeGroup = [];
        groupEnd = -1;
      }
      activeGroup.push(item);
      groupEnd = Math.max(groupEnd, item.end);
    });
    if (activeGroup.length) groups.push(activeGroup);
    groups.forEach((group) => {
      const laneEnds = [];
      group.forEach((item) => {
        let lane = laneEnds.findIndex((endMinute) => endMinute <= item.start);
        if (lane < 0) lane = laneEnds.length;
        laneEnds[lane] = item.end;
        item.lane = lane;
      });
      group.forEach((item) => { item.laneCount = Math.max(1, laneEnds.length); });
    });
    return items;
  }

  function pointerMinutes(event, dayElement) {
    const rect = dayElement.getBoundingClientRect();
    const relative = Math.max(0, Math.min(totalHeight - 1, event.clientY - rect.top));
    const rounded = Math.round(((relative / hourHeight) * 60) / 15) * 15;
    return Math.max(0, Math.min(24 * 60 - 15, rounded));
  }

  function pointerTime(event, dayElement) {
    return minutesToTime(pointerMinutes(event, dayElement));
  }

  function startCreateDrag(domEvent, dateString, dayElement) {
    if (domEvent.button !== 0 || domEvent.pointerType !== "mouse") return;
    if (domEvent.target.closest?.(".calendar-week-event, .calendar-week-resize-handle, button, input, select, textarea")) return;
    const pointerId = domEvent.pointerId;
    const anchorMinutes = pointerMinutes(domEvent, dayElement);
    const initialY = domEvent.clientY;
    createDragRef.current = { pointerId, dateString, anchorMinutes, moved: false };
    setCreatePreview({ date: dateString, startMinutes: anchorMinutes, endMinutes: Math.min(24 * 60, anchorMinutes + 30) });

    const move = (moveEvent) => {
      if (moveEvent.pointerId !== pointerId || !createDragRef.current) return;
      moveEvent.preventDefault();
      autoScrollDuringDrag(moveEvent);
      const currentMinutes = pointerMinutes(moveEvent, dayElement);
      const startMinutes = Math.min(anchorMinutes, currentMinutes);
      const endMinutes = Math.min(24 * 60, Math.max(anchorMinutes, currentMinutes) + 15);
      if (Math.abs(moveEvent.clientY - initialY) > 4) createDragRef.current.moved = true;
      setCreatePreview({ date: dateString, startMinutes, endMinutes: Math.max(startMinutes + 15, endMinutes) });
    };

    const finish = (upEvent) => {
      if (upEvent.pointerId !== pointerId) return;
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", finish);
      window.removeEventListener("pointercancel", finish);
      const state = createDragRef.current;
      if (state?.moved) {
        const currentMinutes = pointerMinutes(upEvent, dayElement);
        const startMinutes = Math.min(anchorMinutes, currentMinutes);
        const endMinutes = Math.min(24 * 60, Math.max(anchorMinutes, currentMinutes) + 15);
        suppressSlotClickRef.current = true;
        if (onRangeCreate) onRangeCreate(dateString, minutesToTime(startMinutes), endMinutes >= 24 * 60 ? "24:00" : minutesToTime(endMinutes));
        else onSlotClick(dateString, minutesToTime(startMinutes));
      }
      createDragRef.current = null;
      setCreatePreview(null);
    };

    window.addEventListener("pointermove", move, { passive: false });
    window.addEventListener("pointerup", finish);
    window.addEventListener("pointercancel", finish);
  }

  function beginDrag(domEvent, eventId) {
    setDragId(eventId);
    domEvent.dataTransfer.effectAllowed = "move";
    domEvent.dataTransfer.setData("text/plain", eventId);
  }

  function autoScrollDuringDrag(domEvent) {
    const root = scrollRef.current;
    if (!root) return;
    const rect = root.getBoundingClientRect();
    const edge = 72;
    if (domEvent.clientY < rect.top + edge) root.scrollTop -= 18;
    else if (domEvent.clientY > rect.bottom - edge) root.scrollTop += 18;
  }

  function startTouchDrag(domEvent, event) {
    if (domEvent.pointerType === "mouse" || domEvent.button !== 0) return;
    const pointerId = domEvent.pointerId;
    let active = false;
    let timer = window.setTimeout(() => { active = true; setDragId(event.id); }, 320);
    const move = (moveEvent) => {
      if (moveEvent.pointerId !== pointerId) return;
      if (!active) return;
      moveEvent.preventDefault();
      autoScrollDuringDrag(moveEvent);
      const column = document.elementFromPoint(moveEvent.clientX, moveEvent.clientY)?.closest?.(".calendar-week-day-column");
      setHoverDay(column?.dataset?.calendarDate || null);
    };
    const finish = (upEvent) => {
      if (upEvent.pointerId !== pointerId) return;
      window.clearTimeout(timer);
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", finish);
      window.removeEventListener("pointercancel", finish);
      if (active) {
        const column = document.elementFromPoint(upEvent.clientX, upEvent.clientY)?.closest?.(".calendar-week-day-column");
        const targetDate = column?.dataset?.calendarDate;
        if (column && targetDate) {
          const time = pointerTime(upEvent, column);
          const duration = calendarDurationMinutes(event);
          touchMovedRef.current = event.id;
          onMoveEvent?.({ ...event, date: targetDate, time, allDay: false, ...calendarEndFields(targetDate, timeToMinutes(time) || 0, duration), estimatedHours: duration / 60 });
        }
      }
      setDragId(null); setHoverDay(null);
    };
    window.addEventListener("pointermove", move, { passive: false });
    window.addEventListener("pointerup", finish);
    window.addEventListener("pointercancel", finish);
  }

  function startResize(domEvent, event) {
    domEvent.preventDefault();
    domEvent.stopPropagation();
    const startMinutes = timeToMinutes(event.time) || 0;
    const initialDuration = calendarDurationMinutes(event);
    const initialY = domEvent.clientY;
    const move = (moveEvent) => {
      const delta = Math.round((((moveEvent.clientY - initialY) / hourHeight) * 60) / 15) * 15;
      const duration = Math.max(15, Math.min(24 * 60, initialDuration + delta));
      setResizePreview({ id: event.id, endMinutes: startMinutes + duration, duration });
    };
    const up = (upEvent) => {
      const delta = Math.round((((upEvent.clientY - initialY) / hourHeight) * 60) / 15) * 15;
      const duration = Math.max(15, Math.min(24 * 60, initialDuration + delta));
      const endFields = calendarEndFields(event.date, startMinutes, duration);
      const updated = { ...event, ...endFields, estimatedHours: duration / 60 };
      setResizePreview(null);
      (onResizeEvent || onMoveEvent)?.(updated);
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up, { once: true });
  }

  function activateEvent(event) {
    if (event.source === "fsrs-review" && onStartReview) onStartReview(event);
    else onEventClick(event);
  }

  function isUnscheduledStudyPlanLecture(event) {
    return Boolean(
      !event.time &&
      !event.allDay &&
      !event.completedAt &&
      event.type !== "exam" &&
      event.source === "study-plan" &&
      (event.lectureId || event.lectureIds?.length)
    );
  }

  const hasUnscheduledLectures = dateStrings.some((key) =>
    calendarEventsForDate(events, key).some(isUnscheduledStudyPlanLecture)
  );

  return (
    <div
      ref={scrollRef}
      className="calendar-week-scroll"
      data-viewport={viewportMode}
      data-density={density}
      onScroll={rememberScrollPosition}
      style={{ "--calendar-days": daysCount, "--calendar-hour-height": `${hourHeight}px` }}
    >
      <div className="calendar-week-sticky-head">
        <div className="calendar-week-header">
          <div className="calendar-week-gutter calendar-week-gutter--header" aria-hidden="true" />
          {days.map((day, index) => {
            const key = dateStrings[index];
            const isToday = key === todayString;
            return (
              <div key={key} className="calendar-week-day-header" data-today={isToday ? "true" : "false"}>
                <button type="button" className="calendar-week-day-button" onClick={() => onSlotClick(key, "09:00")}>
                  <span className="calendar-week-day-name">{weekdayLabels[index]}</span>
                  <span className="calendar-week-day-number">{day.getDate()}</span>
                </button>
              </div>
            );
          })}
        </div>

        {hasUnscheduledLectures && <div className="calendar-week-unscheduled-grid">
          <div className="calendar-week-gutter calendar-week-unscheduled-label">Ikke placeret</div>
          {days.map((day, index) => {
            const key = dateStrings[index];
            const unscheduled = calendarEventsForDate(events, key).filter(isUnscheduledStudyPlanLecture);
            return (
              <div key={key} className="calendar-week-unscheduled-cell" data-empty={!unscheduled.length ? "true" : "false"}>
                {unscheduled.length ? unscheduled.map((event) => (
                  <button
                    key={event.id}
                    type="button"
                    draggable
                    className="calendar-week-unscheduled-chip"
                    data-selected={selectedEventId === event.id ? "true" : "false"}
                    onDragStart={(domEvent) => beginDrag(domEvent, event.id)}
                    onDragEnd={() => setDragId(null)}
                    onClick={() => activateEvent(event)}
                    onContextMenu={(domEvent) => {
                      domEvent.preventDefault();
                      onContextRequest?.({ kind: "unscheduled", event, date: key, x: domEvent.clientX, y: domEvent.clientY });
                    }}
                    title={event.title}
                  >
                    <span>{event.lectureId || "•"}</span><strong>{event.title}</strong>
                  </button>
                )) : <span className="calendar-week-unscheduled-empty">—</span>}
              </div>
            );
          })}
        </div>}
      </div>

      <div className="calendar-week-body" role="grid" aria-label={daysCount === 1 ? "Dagskalender" : "Ugekalender"} style={{ height: totalHeight }}>
        <div className="calendar-week-gutter calendar-week-time-gutter">
          {Array.from({ length: 25 }, (_, index) => (
            <span key={index} className="calendar-week-time-label" style={{ top: index * hourHeight }}>{String(index).padStart(2, "0")}:00</span>
          ))}
        </div>

        {days.map((day, index) => {
          const key = dateStrings[index];
          const dayEvents = calendarEventsForDate(events, key);
          const positioned = layoutEvents(dayEvents);
          const isToday = key === todayString;
          return (
            <div
              key={key}
              className="calendar-week-day-column"
              data-calendar-date={key}
              data-hovered={hoverDay === key ? "true" : "false"}
              role="gridcell"
              tabIndex={0}
              aria-label={`${weekdayLabels[index]} ${day.getDate()}. Tryk Enter for at oprette kl. 09:00`}
              onKeyDown={(event) => { if ((event.key === "Enter" || event.key === " ") && event.target === event.currentTarget) { event.preventDefault(); onSlotClick(key, "09:00"); } }}
              onPointerDown={(event) => startCreateDrag(event, key, event.currentTarget)}
              onClick={(event) => {
                if (suppressSlotClickRef.current) { suppressSlotClickRef.current = false; event.preventDefault(); return; }
                if (event.target.closest?.(".calendar-week-event, .calendar-drag-create-preview")) return;
                onSlotClick(key, pointerTime(event, event.currentTarget));
              }}
              onContextMenu={(event) => {
                if (event.target.closest?.(".calendar-week-event")) return;
                event.preventDefault();
                onContextRequest?.({ kind: "slot", date: key, time: pointerTime(event, event.currentTarget), x: event.clientX, y: event.clientY });
              }}
              onDragOver={(event) => { event.preventDefault(); setHoverDay(key); autoScrollDuringDrag(event); }}
              onDragLeave={() => setHoverDay((value) => value === key ? null : value)}
              onDrop={(event) => {
                event.preventDefault();
                const id = dragId || event.dataTransfer.getData("text/plain");
                const source = events.find((item) => item.id === id);
                if (!source) return;
                const time = pointerTime(event, event.currentTarget);
                const duration = calendarDurationMinutes(source);
                const endFields = calendarEndFields(key, timeToMinutes(time) || 0, duration);
                onMoveEvent({ ...source, date: key, time, allDay: false, ...endFields, estimatedHours: duration / 60 });
                setDragId(null);
                setHoverDay(null);
              }}
              style={{ height: totalHeight }}
            >
              {Array.from({ length: 25 }, (_, lineIndex) => <span key={lineIndex} className="calendar-week-hour-line" style={{ top: lineIndex * hourHeight }} />)}
              {Array.from({ length: 24 }, (_, lineIndex) => <span key={lineIndex} className="calendar-week-half-line" style={{ top: lineIndex * hourHeight + hourHeight / 2 }} />)}
              {isToday && <span className="calendar-week-now-line" style={{ top: nowTop }}><i /></span>}
              {createPreview?.date === key && <div className="calendar-drag-create-preview" style={{ top: (createPreview.startMinutes / 60) * hourHeight + 1, height: Math.max(18, ((createPreview.endMinutes - createPreview.startMinutes) / 60) * hourHeight - 2) }}><span>{minutesToTime(createPreview.startMinutes)}–{createPreview.endMinutes >= 24 * 60 ? "24:00" : minutesToTime(createPreview.endMinutes)}</span></div>}

              {positioned.map(({ event, start, end, lane, laneCount }) => {
                const tone = calendarActivityTone(c, event);
                const visibleStart = Math.max(0, start);
                const visibleEnd = Math.min(24 * 60, end);
                const top = (visibleStart / 60) * hourHeight;
                const height = Math.max(24, ((visibleEnd - visibleStart) / 60) * hourHeight - 2);
                const hasConflict = events.some((other) => calendarEventsConflict(event, other));
                return (
                  <button
                    key={`${event.id}-${key}`}
                    type="button"
                    draggable
                    className="calendar-week-event"
                    data-complete={event.completedAt ? "true" : "false"}
                    data-source={calendarEventLayer(event)}
                    data-conflict={hasConflict ? "true" : "false"}
                    data-selected={selectedEventId === event.id ? "true" : "false"}
                    onDragStart={(domEvent) => beginDrag(domEvent, event.id)}
                    onDragEnd={() => setDragId(null)}
                    onPointerDown={(domEvent) => startTouchDrag(domEvent, event)}
                    onClick={(domEvent) => { domEvent.stopPropagation(); if (touchMovedRef.current === event.id) { touchMovedRef.current = null; domEvent.preventDefault(); return; } activateEvent(event); }}
                    onContextMenu={(domEvent) => {
                      domEvent.preventDefault();
                      domEvent.stopPropagation();
                      onContextRequest?.({ kind: "event", event, date: key, x: domEvent.clientX, y: domEvent.clientY });
                    }}
                    style={{
                      top: top + 1,
                      height,
                      width: `calc(${100 / laneCount}% - 6px)`,
                      insetInlineStart: `calc(${lane * (100 / laneCount)}% + 3px)`,
                      "--calendar-event-accent": tone.color,
                      "--calendar-event-surface": tone.background,
                    }}
                    title={`${event.time || ""} ${event.title}`.trim()}
                  >
                    <span className="calendar-week-event-time">{event._segmentContinuation ? "Fortsætter" : `${event.time}–${event.endTime || calendarEndFields(event.date, start, end - start).endTime}`}</span>
                    <span className="calendar-week-event-title">{event.title}</span>
                    <span className="calendar-week-event-meta">{event.location || tone.label}</span>
                    {event.deliveryStatus === "held" && <span className="calendar-week-event-state">Afholdt</span>}
                    <span className="calendar-week-resize-handle" onPointerDown={(domEvent) => startResize(domEvent, event)} aria-hidden="true" />
                  </button>
                );
              })}
            </div>
          );
        })}
      </div>
      {Number.isFinite(initialScrollMinutes) && <div className="calendar-week-scroll-tail" aria-hidden="true" />}
    </div>
  );
}


function MonthCalendar({ c, events, monthDate, onDayClick, onEventClick, onContextRequest, weekdayLabels }) {
  const year = monthDate.getFullYear();
  const month = monthDate.getMonth();
  const cells = getMonthMatrix(year, month);
  const todayKeyStr = dateKey(new Date().getFullYear(), new Date().getMonth(), new Date().getDate());
  return (
    <div className="calendar-month-root">
      <div className="calendar-month-weekdays">{weekdayLabels.map((label) => <div key={label}>{label}</div>)}</div>
      <div className="calendar-month-grid">
        {cells.map((day, index) => {
          if (!day) return <div key={`empty-${index}`} className="calendar-month-cell calendar-month-cell--empty" />;
          const key = dateKey(year, month, day);
          const dayEvents = calendarEventsForDate(events, key).filter((event) => !event.allDay).sort((a, b) => (a.time || "99:99").localeCompare(b.time || "99:99"));
          const unscheduled = dayEvents.filter((event) => !event.time && !event.allDay && !event.completedAt && event.type !== "exam");
          return (
            <div key={key} className="calendar-month-cell" data-today={key === todayKeyStr ? "true" : "false"} onClick={() => onDayClick(key)} onContextMenu={(event) => { if (event.target !== event.currentTarget) return; event.preventDefault(); onContextRequest?.({ kind: "slot", date: key, time: "09:00", x: event.clientX, y: event.clientY }); }}>
              <span className="calendar-month-day-number">{day}</span>
              {unscheduled.length > 0 && <span className="calendar-month-unscheduled-count">{unscheduled.length} ikke placeret</span>}
              <div className="calendar-month-events">
                {dayEvents.slice(0, 5).map((event) => {
                  const tone = calendarActivityTone(c, event);
                  return <button key={`${event.id}-${key}`} type="button" className="calendar-month-event" data-unscheduled={!event.time && !event.allDay ? "true" : "false"} data-complete={event.completedAt ? "true" : "false"} style={{ "--calendar-month-accent": tone.color }} onClick={(domEvent) => { domEvent.stopPropagation(); onEventClick(event); }} onContextMenu={(domEvent) => { domEvent.preventDefault(); domEvent.stopPropagation(); onContextRequest?.({ kind: event.time ? "event" : "unscheduled", event, date: key, x: domEvent.clientX, y: domEvent.clientY }); }}><span>{event.time || "Ikke placeret"}</span><strong>{event.title}</strong></button>;
                })}
                {dayEvents.length > 5 && <small className="calendar-month-more">+{dayEvents.length - 5}</small>}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}


function loadStorage(key, fallback) {
  try {
    const value = localStorage.getItem(key);
    return value ? JSON.parse(value) : fallback;
  } catch {
    return fallback;
  }
}

function useStoredState(key, fallback) {
  const [value, setValue] = useState(() => loadStorage(key, fallback));
  const isFirstWrite = useRef(true);
  const skipNextDispatch = useRef(false);

  useEffect(() => {
    if (isFirstWrite.current) {
      isFirstWrite.current = false;
      return;
    }
    try {
      localStorage.setItem(key, JSON.stringify(value));
      // Notify every other useStoredState instance watching this same key (e.g. Settings
      // and the Dr. Byte chat panel both read STORAGE.aiSettings independently) so they
      // stay in sync without requiring a full remount. Skip the dispatch if this write was
      // itself caused by an incoming external-update event, to avoid an infinite ping-pong
      // between multiple components sharing the same storage key.
      if (skipNextDispatch.current) {
        skipNextDispatch.current = false;
      } else {
        window.dispatchEvent(new CustomEvent("medlearn-storage-update", { detail: { key } }));
      }
    } catch {
      // Ignorer browser storage-fejl.
    }
  }, [key, value]);

  useEffect(() => {
    function handleExternalUpdate(event) {
      if (event.detail && event.detail.key === key) {
        skipNextDispatch.current = true;
        setValue(loadStorage(key, fallback));
      }
    }
    window.addEventListener("medlearn-storage-update", handleExternalUpdate);
    return () => window.removeEventListener("medlearn-storage-update", handleExternalUpdate);
  }, [key]);

  return [value, setValue];
}

const CLOUD_SYNCED_KEYS = {
  [STORAGE.studyPlans]: { table: "study_plans", type: "keyed_object" },
  [STORAGE.calendarEvents]: { table: "calendar_events", type: "calendar" },
  [STORAGE.calendarEventMeta]: { table: "calendar_events", type: "calendar" },
};
const cloudSyncTimers = new Map();

async function pullQuestionBankIntoLocalStorage() {
  const { data, error } = await supabase
    .from("question_bank")
    .select(`id,module_id,lecture_id,category,content,created_at`)
    .eq("status", "published")
    .order("created_at", { ascending: true });
  if (error) throw error;
  const questionsArray = (data || []).map((row) => {
    const content = row.content && typeof row.content === "object" && !Array.isArray(row.content) ? row.content : {};
    return normalizeImportedQuestion({ ...content, id: row.id, moduleId: row.module_id, lectureId: row.lecture_id, category: content.category || row.category || "Ukategoriseret" });
  }).filter((question) => question.id && question.moduleId && question.question && question.options.length >= 2);
  localStorage.setItem(STORAGE.importedQuestions, JSON.stringify(questionsArray));
  window.dispatchEvent(new CustomEvent("medlearn-storage-update", { detail: { key: STORAGE.importedQuestions } }));
  return questionsArray;
}

function calendarEmitSync(status, detail = "") {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new CustomEvent("medlearn-calendar-sync", { detail: { status, detail, at: Date.now() } }));
}

async function pullCloudDataIntoLocalStorage(userId) {
  try {
    calendarEmitSync("syncing", "Henter kalender");
    await pullQuestionBankIntoLocalStorage();
    const { data: events, error: eventsError } = await supabase.from("calendar_events").select("*").eq("user_id", userId);
    if (eventsError) throw eventsError;
    const eventsArray = (events || []).map((row) => ({
      id: row.id,
      title: row.title,
      date: row.date,
      time: row.time || "",
      type: row.type || "other",
      planModuleId: row.plan_module_id || null,
      lectureCount: row.lecture_count || null,
      estimatedHours: row.estimated_hours || null,
    }));
    const metadata = Object.fromEntries((events || []).map((row) => [row.id, row.metadata && typeof row.metadata === "object" ? row.metadata : {}]));
    localStorage.setItem(STORAGE.calendarEvents, JSON.stringify(eventsArray));
    localStorage.setItem(STORAGE.calendarEventMeta, JSON.stringify(metadata));
    [STORAGE.calendarEvents, STORAGE.calendarEventMeta].forEach((key) => window.dispatchEvent(new CustomEvent("medlearn-storage-update", { detail: { key } })));
    calendarEmitSync("synced", "Kalender hentet");
  } catch (error) {
    calendarEmitSync("error", error?.message || "Synkronisering fejlede");
    console.error("Kunne ikke hente cloud-data fra Supabase:", error);
  }
}

async function pushCalendarStateToCloud(userId) {
  calendarEmitSync("syncing", "Gemmer kalender");
  const eventsArray = loadStorage(STORAGE.calendarEvents, []);
  const metadata = loadStorage(STORAGE.calendarEventMeta, {});
  const rows = eventsArray.map((event) => ({
    id: event.id,
    user_id: userId,
    title: event.title,
    date: event.date,
    time: event.time || null,
    type: event.type || "other",
    plan_module_id: event.planModuleId || null,
    lecture_count: event.lectureCount || null,
    estimated_hours: event.estimatedHours || null,
    metadata: metadata[event.id] || {},
    updated_at: new Date().toISOString(),
  }));
  if (rows.length) {
    const { error } = await supabase.from("calendar_events").upsert(rows, { onConflict: "id" });
    if (error) throw error;
  }
  const { data: remoteRows, error: selectError } = await supabase.from("calendar_events").select("id").eq("user_id", userId);
  if (selectError) throw selectError;
  const localIds = new Set(rows.map((row) => row.id));
  const staleIds = (remoteRows || []).map((row) => row.id).filter((id) => !localIds.has(id));
  if (staleIds.length) {
    const { error: deleteError } = await supabase.from("calendar_events").delete().eq("user_id", userId).in("id", staleIds);
    if (deleteError) throw deleteError;
  }
  calendarEmitSync("synced", "Kalender gemt");
}

async function pushLocalStorageKeyToCloud(key, userId) {
  const config = CLOUD_SYNCED_KEYS[key];
  if (!config || !userId) return;
  try {
    if (config.type === "calendar") {
      await pushCalendarStateToCloud(userId);
      return;
    }
    if (key === STORAGE.studyPlans) {
      const plansObject = loadStorage(STORAGE.studyPlans, {});
      const rows = Object.entries(plansObject).map(([moduleName, data]) => ({ user_id: userId, module_name: moduleName, data, updated_at: new Date().toISOString() }));
      if (rows.length) {
        const { error } = await supabase.from("study_plans").upsert(rows, { onConflict: "user_id,module_name" });
        if (error) throw error;
      }
    }
  } catch (error) {
    calendarEmitSync("error", error?.message || "Synkronisering fejlede");
    console.error("Kunne ikke skrive data til Supabase:", error);
  }
}

function useCloudSync(userId) {
  useEffect(() => {
    if (!userId) return;
    pullCloudDataIntoLocalStorage(userId);
  }, [userId]);

  useEffect(() => {
    if (!userId) return;
    function handleUpdate(event) {
      const key = event.detail && event.detail.key;
      if (!key || !CLOUD_SYNCED_KEYS[key]) return;
      const timerKey = CLOUD_SYNCED_KEYS[key].type === "calendar" ? "calendar" : key;
      window.clearTimeout(cloudSyncTimers.get(timerKey));
      cloudSyncTimers.set(timerKey, window.setTimeout(() => pushLocalStorageKeyToCloud(key, userId), 350));
    }
    async function handleReconnect() {
      calendarEmitSync("syncing", "Forbinder og sender lokale ændringer");
      await pushLocalStorageKeyToCloud(STORAGE.calendarEvents, userId);
      await pushLocalStorageKeyToCloud(STORAGE.studyPlans, userId);
    }
    window.addEventListener("medlearn-storage-update", handleUpdate);
    window.addEventListener("online", handleReconnect);
    return () => {
      window.removeEventListener("medlearn-storage-update", handleUpdate);
      window.removeEventListener("online", handleReconnect);
    };
  }, [userId]);
}


function translate(value, language, fallback = "da") {
  if (typeof value === "string") return value;
  if (!value || typeof value !== "object") return "";
  return value[language] || value[fallback] || value.en || "";
}

/*
  Brug denne funktion på spørgsmål, der importeres senere.
  Gamle spørgsmål med ren tekst får automatisk samme tekst som fallback
  på alle tre sprog, indtil rigtige oversættelser tilføjes.
*/
export function normalizeImportedQuestion(rawQuestion) {
  const id =
    rawQuestion.id ||
    `question-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

  function localized(value) {
    if (typeof value === "string") {
      return { da: value, en: value, ar: value };
    }

    return value || { da: "", en: "", ar: "" };
  }

  return {
    id,
    moduleId: rawQuestion.moduleId || null,
    lectureId: rawQuestion.lectureId || null,
    category: localized(rawQuestion.category || "Ukategoriseret"),
    question: localized(rawQuestion.question || rawQuestion.text || ""),
    options: (rawQuestion.options || []).map(localized),
    correct: Number(rawQuestion.correct ?? 0),
    explanation: localized(rawQuestion.explanation || ""),
  };
}

/* =============================================================================
   LEGACY ANKI SM-2 SCHEDULER (app-51)
   ---------------------------------------------------------------------------
   Replaces the previous simplified scheduleCard()/isDue()/cardStatus() trio
   with a faithful legacy SuperMemo-2 implementation matching Anki's classic
   scheduler. Card shape is DEEPLY compatible with the old shape used across
   this file (dueDate, easeFactor, interval, repetitions) so every existing
   call site (buildQuestionPool, dashboards, Insights status pills, due
   counters) keeps working without modification, while gaining full state
   machine behaviour (new/learning/review/relearning/suspended), configurable
   deck settings, fuzz, leeches and a complete review log.
   ========================================================================== */

const SM2_DEFAULT_DECK_SETTINGS = Object.freeze({
  new: {
    learningStepsMinutes: [1, 10],
    graduatingIntervalDays: 1,
    easyIntervalDays: 4,
  },
  lapse: {
    relearningStepsMinutes: [10],
    minIntervalAfterLapseDays: 1,
    newIntervalPercent: 0,
    leechThreshold: 8,
    leechAction: "suspend",
  },
  review: {
    startingEase: 2.5,
    hardIntervalMultiplier: 1.2,
    easyBonus: 1.3,
    intervalModifier: 1.0,
    maximumIntervalDays: 36500,
  },
  fuzz: {
    enabled: true,
    learningStepMaxExtraMinutes: 5,
  },
});

const SM2_CARD_STATE = Object.freeze({
  NEW: "new",
  LEARNING: "learning",
  REVIEW: "review",
  RELEARNING: "relearning",
  SUSPENDED: "suspended",
});

const SM2_RATING = Object.freeze({ AGAIN: 1, HARD: 2, GOOD: 3, EASY: 4 });

const SM2_MIN_EASE = 1.3;
const SM2_MS_PER_MIN = 60 * 1000;
const SM2_MS_PER_DAY = 24 * 60 * SM2_MS_PER_MIN;


/* =============================================================================
   OFFICIAL FSRS-6 RUNTIME — ts-fsrs 5.4.1
   ---------------------------------------------------------------------------
   Interval math and card-state transitions are delegated to the official
   open-spaced-repetition TypeScript implementation used to build Anki-style
   FSRS review flows. It is version-pinned and loaded as an ESM module at
   runtime because this project currently ships as a single App.js file.

   The older SM-2 implementation below remains only as a compatibility/offline
   fallback for existing cards and for the brief moment before the module has
   loaded. Once FSRS is available, all new ratings are committed by FSRS-6.
   ========================================================================== */
const FSRS_RUNTIME_VERSION = "ts-fsrs@5.4.1 / FSRS-6";
const FSRS_ESM_URL = "https://cdn.jsdelivr.net/npm/ts-fsrs@5.4.1/+esm";
const FSRS_DEFAULT_SETTINGS = Object.freeze({
  requestRetention: 0.9,
  maximumInterval: 36500,
  enableFuzz: true,
  enableShortTerm: true,
  learningSteps: ["1m", "10m"],
  relearningSteps: ["10m"],
});
let officialFsrsPromise = null;
let officialFsrsModule = null;

function loadOfficialFsrs() {
  if (officialFsrsModule) return Promise.resolve(officialFsrsModule);
  if (!officialFsrsPromise) {
    officialFsrsPromise = import(/* webpackIgnore: true */ FSRS_ESM_URL)
      .then((module) => {
        officialFsrsModule = module;
        return module;
      })
      .catch((error) => {
        officialFsrsPromise = null;
        throw new Error(`Flashkortmotoren kunne ikke indlæses: ${error?.message || error}`);
      });
  }
  return officialFsrsPromise;
}

function fsrsReadSettings() {
  const stored = loadStorage(STORAGE.fsrsSettings, FSRS_DEFAULT_SETTINGS);
  const retention = Number(stored?.requestRetention);
  return {
    requestRetention: Number.isFinite(retention) ? Math.max(.7, Math.min(.99, retention)) : .9,
    maximumInterval: Math.max(1, Math.min(36500, Number(stored?.maximumInterval) || 36500)),
    enableFuzz: stored?.enableFuzz !== false,
    enableShortTerm: stored?.enableShortTerm !== false,
    learningSteps: Array.isArray(stored?.learningSteps) && stored.learningSteps.length ? stored.learningSteps : ["1m", "10m"],
    relearningSteps: Array.isArray(stored?.relearningSteps) && stored.relearningSteps.length ? stored.relearningSteps : ["10m"],
  };
}

function fsrsSchedulerFromModule(module, override) {
  const settings = { ...fsrsReadSettings(), ...(override || {}) };
  return module.fsrs({
    request_retention: settings.requestRetention,
    maximum_interval: settings.maximumInterval,
    enable_fuzz: settings.enableFuzz,
    enable_short_term: settings.enableShortTerm,
    learning_steps: settings.learningSteps,
    relearning_steps: settings.relearningSteps,
  });
}

function fsrsSerializeDate(value) {
  if (!value) return null;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

function fsrsSerializeCard(card) {
  return {
    ...card,
    due: fsrsSerializeDate(card.due),
    last_review: fsrsSerializeDate(card.last_review),
  };
}

function fsrsSerializeLog(log) {
  return {
    ...log,
    due: fsrsSerializeDate(log?.due),
    review: fsrsSerializeDate(log?.review),
  };
}

function fsrsReviveDate(value, fallback) {
  const date = value ? new Date(value) : fallback;
  return date instanceof Date && !Number.isNaN(date.getTime()) ? date : fallback;
}

function fsrsStateName(state) {
  return ({ 0: "new", 1: "learning", 2: "review", 3: "relearning" })[Number(state)] || "new";
}

function fsrsReviveCard(storedCard, questionId, module, now = new Date()) {
  const persisted = storedCard?.fsrs?.card;
  if (persisted) {
    return {
      ...persisted,
      due: fsrsReviveDate(persisted.due, now),
      last_review: persisted.last_review ? fsrsReviveDate(persisted.last_review, null) : undefined,
    };
  }

  const fresh = module.createEmptyCard(now);
  if (!storedCard?.dueDate && !storedCard?.sm2) return fresh;

  // A legacy SM-2 card has no complete FSRS review history. We preserve its
  // due date and approximate its first memory state, then let FSRS take over.
  const intervalDays = Math.max(0, Number(storedCard?.interval ?? storedCard?.sm2?.intervalDays) || 0);
  const reps = Math.max(0, Number(storedCard?.repetitions ?? storedCard?.sm2?.repsCorrectInARow) || 0);
  return {
    ...fresh,
    due: fsrsReviveDate(storedCard?.dueDate || storedCard?.sm2?.due, now),
    stability: Math.max(.1, intervalDays || .1),
    difficulty: 5,
    elapsed_days: 0,
    scheduled_days: Math.round(intervalDays),
    reps,
    lapses: Math.max(0, Number(storedCard?.sm2?.lapses) || 0),
    state: reps > 0 ? module.State.Review : module.State.New,
    last_review: storedCard?.sm2?.lastReviewedAt ? new Date(storedCard.sm2.lastReviewedAt) : undefined,
  };
}

function fsrsResultToStored(result, previous, rating, questionId) {
  const card = result.card;
  const dueDate = fsrsSerializeDate(card.due);
  const previousReviews = Array.isArray(previous?.fsrs?.reviews) ? previous.fsrs.reviews : [];
  return {
    interval: Math.max(0, Number(card.scheduled_days) || 0),
    easeFactor: null,
    repetitions: Math.max(0, Number(card.reps) || 0),
    dueDate,
    lastResult: rating !== SM2_RATING.AGAIN,
    id: questionId,
    fsrs: {
      version: FSRS_RUNTIME_VERSION,
      migration: previous?.fsrs?.migration || (previous?.sm2 ? "legacy-sm2-compat" : null),
      card: fsrsSerializeCard(card),
      reviews: [...previousReviews, fsrsSerializeLog(result.log)].slice(-500),
      lastRating: rating,
      updatedAt: Date.now(),
    },
  };
}

async function fsrsPreviewOfficial(storedCard, questionId, nowMs = Date.now()) {
  const module = await loadOfficialFsrs();
  const now = new Date(nowMs);
  const scheduler = fsrsSchedulerFromModule(module);
  const card = fsrsReviveCard(storedCard, questionId, module, now);
  const preview = scheduler.repeat(card, now);
  const ratingMap = {
    [SM2_RATING.AGAIN]: module.Rating.Again,
    [SM2_RATING.HARD]: module.Rating.Hard,
    [SM2_RATING.GOOD]: module.Rating.Good,
    [SM2_RATING.EASY]: module.Rating.Easy,
  };
  return Object.fromEntries(Object.entries(ratingMap).map(([localRating, officialRating]) => {
    const item = preview[officialRating];
    const due = item?.card?.due instanceof Date ? item.card.due : new Date(item?.card?.due || now);
    return [Number(localRating), {
      ...item,
      dueAt: due.getTime(),
      delayMs: Math.max(0, due.getTime() - nowMs),
      newState: fsrsStateName(item?.card?.state),
      newIntervalDays: Number(item?.card?.scheduled_days) || 0,
      isLeech: false,
    }];
  }));
}

async function fsrsApplyOfficial(storedCard, rating, questionId, nowMs = Date.now()) {
  const module = await loadOfficialFsrs();
  const now = new Date(nowMs);
  const scheduler = fsrsSchedulerFromModule(module);
  const card = fsrsReviveCard(storedCard, questionId, module, now);
  const officialRating = ({
    [SM2_RATING.AGAIN]: module.Rating.Again,
    [SM2_RATING.HARD]: module.Rating.Hard,
    [SM2_RATING.GOOD]: module.Rating.Good,
    [SM2_RATING.EASY]: module.Rating.Easy,
  })[rating];
  const result = scheduler.next(card, now, officialRating);
  return fsrsResultToStored(result, storedCard, rating, questionId);
}

function sm2CreateNewCard(id, deckId = "default") {
  return {
    id,
    deckId,
    state: SM2_CARD_STATE.NEW,
    intervalDays: 0,
    ease: null,
    repsCorrectInARow: 0,
    lapses: 0,
    learningStepIndex: 0,
    relearningStepIndex: 0,
    due: null,
    lastReviewedAt: null,
    isLeech: false,
    reviewLog: [],
  };
}

function sm2SeededRandom(seed) {
  let s = seed % 2147483647;
  if (s <= 0) s += 2147483646;
  return () => {
    s = (s * 16807) % 2147483647;
    return (s - 1) / 2147483646;
  };
}
function sm2FuzzSeedFor(cardId, atMs) {
  let h = 0;
  const str = `${cardId}:${atMs}`;
  for (let i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) | 0;
  return Math.abs(h) || 1;
}
function sm2FuzzRangeDays(intervalDays) {
  if (intervalDays < 2.5) return 0;
  if (intervalDays < 7) return 0.15 * intervalDays;
  if (intervalDays < 30) return Math.max(1, 0.1 * intervalDays);
  return Math.max(2, 0.05 * intervalDays);
}
function sm2ApplyFuzzDays(intervalDays, cardId, nowMs, maxIntervalDays) {
  const range = sm2FuzzRangeDays(intervalDays);
  if (range <= 0) return { fuzzedDays: Math.round(intervalDays) };
  const rnd = sm2SeededRandom(sm2FuzzSeedFor(cardId, nowMs))();
  const delta = Math.round((rnd * 2 - 1) * range);
  let fuzzed = Math.round(intervalDays) + delta;
  fuzzed = Math.max(1, Math.min(maxIntervalDays, fuzzed));
  return { fuzzedDays: fuzzed };
}
function sm2ApplyFuzzMinutes(minutes, seedKey, nowMs, maxExtraMinutes) {
  if (!maxExtraMinutes) return { fuzzedMinutes: minutes };
  const rnd = sm2SeededRandom(sm2FuzzSeedFor(seedKey, nowMs) + 1)();
  const extra = Math.round(rnd * maxExtraMinutes);
  return { fuzzedMinutes: minutes + extra };
}

function sm2FormatIntervalDa(ms) {
  const minutes = ms / SM2_MS_PER_MIN;
  if (minutes < 1) return "<1 min";
  if (minutes < 60) return `${Math.round(minutes)} min`;
  const hours = minutes / 60;
  if (hours < 24) return `${Math.round(hours)} t`;
  const days = Math.round(ms / SM2_MS_PER_DAY);
  return days === 1 ? "1 dag" : `${days} dage`;
}

function sm2PreviewRating(card, settings, rating, nowMs = Date.now()) {
  return sm2ComputeOutcome(card, settings, rating, nowMs);
}

function sm2ApplyRating(card, settings, rating, nowMs = Date.now()) {
  const outcome = sm2ComputeOutcome(card, settings, rating, nowMs);
  const wasOverdue = card.due != null && nowMs > card.due;
  const logEntry = {
    timestamp: nowMs,
    stateBefore: card.state,
    rating,
    shownIntervalMs: outcome.delayMs,
    assignedIntervalDays: outcome.newIntervalDays ?? null,
    easeBefore: card.ease,
    easeAfter: outcome.newEase,
    wasOverdue,
  };
  return {
    ...card,
    state: outcome.newState,
    intervalDays: outcome.newIntervalDays ?? card.intervalDays,
    ease: outcome.newEase,
    repsCorrectInARow: outcome.repsCorrectInARow,
    lapses: outcome.newLapses,
    learningStepIndex: outcome.newLearningStepIndex,
    relearningStepIndex: outcome.newRelearningStepIndex,
    due: outcome.dueAt,
    lastReviewedAt: nowMs,
    isLeech: outcome.isLeech,
    reviewLog: [...(card.reviewLog || []), logEntry],
  };
}

function sm2ComputeOutcome(card, settings, rating, nowMs) {
  if (card.state === SM2_CARD_STATE.NEW || card.state === SM2_CARD_STATE.LEARNING) {
    return sm2ComputeLearningOutcome(card, settings, rating, nowMs);
  }
  if (card.state === SM2_CARD_STATE.RELEARNING) {
    return sm2ComputeRelearningOutcome(card, settings, rating, nowMs);
  }
  if (card.state === SM2_CARD_STATE.REVIEW) {
    return sm2ComputeReviewOutcome(card, settings, rating, nowMs);
  }
  throw new Error(`Cannot rate a suspended/unknown-state card: ${card.state}`);
}

function sm2ComputeLearningOutcome(card, settings, rating, nowMs) {
  const steps = settings.new.learningStepsMinutes;
  const stepIdx = card.state === SM2_CARD_STATE.NEW ? 0 : card.learningStepIndex;

  if (rating === SM2_RATING.EASY) {
    const days = settings.new.easyIntervalDays;
    const { fuzzedDays } = sm2ApplyFuzzDays(days, card.id, nowMs, settings.review.maximumIntervalDays);
    return {
      newState: SM2_CARD_STATE.REVIEW, newIntervalDays: fuzzedDays,
      newEase: card.ease ?? settings.review.startingEase, repsCorrectInARow: 1,
      newLapses: card.lapses, newLearningStepIndex: 0, newRelearningStepIndex: card.relearningStepIndex,
      dueAt: sm2DayKeyFromNow(nowMs, fuzzedDays), isLeech: card.isLeech, delayMs: fuzzedDays * SM2_MS_PER_DAY,
    };
  }
  if (rating === SM2_RATING.AGAIN) {
    const delayMin = sm2MinutesWithFuzz(steps[0], card, settings, nowMs, "again0");
    return {
      newState: SM2_CARD_STATE.LEARNING, newIntervalDays: 0, newEase: card.ease, repsCorrectInARow: 0,
      newLapses: card.lapses, newLearningStepIndex: 0, newRelearningStepIndex: card.relearningStepIndex,
      dueAt: nowMs + delayMin * SM2_MS_PER_MIN, isLeech: card.isLeech, delayMs: steps[0] * SM2_MS_PER_MIN,
    };
  }
  if (rating === SM2_RATING.HARD) {
    let nominalMin;
    if (steps.length === 1) nominalMin = Math.min(steps[0] * 1.5, steps[0] + 24 * 60);
    else if (stepIdx === 0) nominalMin = (steps[0] + steps[1]) / 2;
    else nominalMin = steps[stepIdx];
    const delayMin = sm2MinutesWithFuzz(nominalMin, card, settings, nowMs, "hard");
    return {
      newState: SM2_CARD_STATE.LEARNING, newIntervalDays: 0, newEase: card.ease, repsCorrectInARow: 0,
      newLapses: card.lapses, newLearningStepIndex: stepIdx, newRelearningStepIndex: card.relearningStepIndex,
      dueAt: sm2CrossesDayBoundary(delayMin) ? sm2DayKeyFromNow(nowMs, Math.max(1, Math.round(delayMin / 1440))) : nowMs + delayMin * SM2_MS_PER_MIN,
      isLeech: card.isLeech, delayMs: nominalMin * SM2_MS_PER_MIN,
    };
  }
  const nextIdx = stepIdx + 1;
  if (nextIdx >= steps.length) {
    const days = settings.new.graduatingIntervalDays;
    const { fuzzedDays } = sm2ApplyFuzzDays(days, card.id, nowMs, settings.review.maximumIntervalDays);
    return {
      newState: SM2_CARD_STATE.REVIEW, newIntervalDays: fuzzedDays,
      newEase: card.ease ?? settings.review.startingEase, repsCorrectInARow: 1,
      newLapses: card.lapses, newLearningStepIndex: 0, newRelearningStepIndex: card.relearningStepIndex,
      dueAt: sm2DayKeyFromNow(nowMs, fuzzedDays), isLeech: card.isLeech, delayMs: fuzzedDays * SM2_MS_PER_DAY,
    };
  }
  const nextStepMin = steps[nextIdx];
  const delayMin = sm2MinutesWithFuzz(nextStepMin, card, settings, nowMs, "good");
  return {
    newState: SM2_CARD_STATE.LEARNING, newIntervalDays: 0, newEase: card.ease, repsCorrectInARow: 0,
    newLapses: card.lapses, newLearningStepIndex: nextIdx, newRelearningStepIndex: card.relearningStepIndex,
    dueAt: sm2CrossesDayBoundary(delayMin) ? sm2DayKeyFromNow(nowMs, Math.max(1, Math.round(delayMin / 1440))) : nowMs + delayMin * SM2_MS_PER_MIN,
    isLeech: card.isLeech, delayMs: nextStepMin * SM2_MS_PER_MIN,
  };
}

function sm2ComputeRelearningOutcome(card, settings, rating, nowMs) {
  const steps = settings.lapse.relearningStepsMinutes;
  const stepIdx = card.relearningStepIndex;
  if (rating === SM2_RATING.AGAIN) {
    const delayMin = sm2MinutesWithFuzz(steps[0], card, settings, nowMs, "relearn-again");
    return {
      newState: SM2_CARD_STATE.RELEARNING, newIntervalDays: card.intervalDays, newEase: card.ease, repsCorrectInARow: 0,
      newLapses: card.lapses, newLearningStepIndex: card.learningStepIndex, newRelearningStepIndex: 0,
      dueAt: nowMs + delayMin * SM2_MS_PER_MIN, isLeech: card.isLeech, delayMs: steps[0] * SM2_MS_PER_MIN,
    };
  }
  if (rating === SM2_RATING.HARD) {
    const nominalMin = steps[stepIdx] ?? steps[steps.length - 1];
    const delayMin = sm2MinutesWithFuzz(nominalMin, card, settings, nowMs, "relearn-hard");
    return {
      newState: SM2_CARD_STATE.RELEARNING, newIntervalDays: card.intervalDays, newEase: card.ease, repsCorrectInARow: 0,
      newLapses: card.lapses, newLearningStepIndex: card.learningStepIndex, newRelearningStepIndex: stepIdx,
      dueAt: nowMs + delayMin * SM2_MS_PER_MIN, isLeech: card.isLeech, delayMs: nominalMin * SM2_MS_PER_MIN,
    };
  }
  const days = card.intervalDays;
  const { fuzzedDays } = sm2ApplyFuzzDays(days, card.id, nowMs, settings.review.maximumIntervalDays);
  return {
    newState: SM2_CARD_STATE.REVIEW, newIntervalDays: fuzzedDays, newEase: card.ease, repsCorrectInARow: 1,
    newLapses: card.lapses, newLearningStepIndex: card.learningStepIndex, newRelearningStepIndex: 0,
    dueAt: sm2DayKeyFromNow(nowMs, fuzzedDays), isLeech: card.isLeech, delayMs: fuzzedDays * SM2_MS_PER_DAY,
  };
}

function sm2ComputeReviewOutcome(card, settings, rating, nowMs) {
  const rs = settings.review;
  const prevInterval = card.intervalDays;
  const prevEase = card.ease ?? rs.startingEase;
  const maxDays = rs.maximumIntervalDays;

  if (rating === SM2_RATING.AGAIN) {
    const newEase = Math.max(SM2_MIN_EASE, prevEase - 0.20);
    const retainedDays = Math.max(settings.lapse.minIntervalAfterLapseDays, Math.round(prevInterval * (settings.lapse.newIntervalPercent / 100)));
    const cappedDays = Math.min(maxDays, retainedDays);
    const newLapses = card.lapses + 1;
    const hitLeech = newLapses >= settings.lapse.leechThreshold;
    if (hitLeech && settings.lapse.leechAction === "suspend") {
      return {
        newState: SM2_CARD_STATE.SUSPENDED, newIntervalDays: cappedDays, newEase, repsCorrectInARow: 0, newLapses,
        newLearningStepIndex: card.learningStepIndex, newRelearningStepIndex: 0, dueAt: card.due, isLeech: true, delayMs: null,
      };
    }
    const relearnSteps = settings.lapse.relearningStepsMinutes;
    if (relearnSteps && relearnSteps.length > 0) {
      const delayMin = sm2MinutesWithFuzz(relearnSteps[0], card, settings, nowMs, "lapse-relearn");
      return {
        newState: SM2_CARD_STATE.RELEARNING, newIntervalDays: cappedDays, newEase, repsCorrectInARow: 0, newLapses,
        newLearningStepIndex: card.learningStepIndex, newRelearningStepIndex: 0, dueAt: nowMs + delayMin * SM2_MS_PER_MIN,
        isLeech: hitLeech, delayMs: relearnSteps[0] * SM2_MS_PER_MIN,
      };
    }
    const { fuzzedDays } = sm2ApplyFuzzDays(cappedDays, card.id, nowMs, maxDays);
    return {
      newState: SM2_CARD_STATE.REVIEW, newIntervalDays: fuzzedDays, newEase, repsCorrectInARow: 0, newLapses,
      newLearningStepIndex: card.learningStepIndex, newRelearningStepIndex: 0, dueAt: sm2DayKeyFromNow(nowMs, fuzzedDays),
      isLeech: hitLeech, delayMs: fuzzedDays * SM2_MS_PER_DAY,
    };
  }

  if (rating === SM2_RATING.HARD) {
    const newEase = Math.max(SM2_MIN_EASE, prevEase - 0.15);
    const candidate = Math.min(maxDays, prevInterval * rs.hardIntervalMultiplier * rs.intervalModifier);
    const { fuzzedDays } = sm2ApplyFuzzDays(candidate, card.id, nowMs, maxDays);
    return {
      newState: SM2_CARD_STATE.REVIEW, newIntervalDays: fuzzedDays, newEase, repsCorrectInARow: card.repsCorrectInARow + 1,
      newLapses: card.lapses, newLearningStepIndex: card.learningStepIndex, newRelearningStepIndex: 0,
      dueAt: sm2DayKeyFromNow(nowMs, fuzzedDays), isLeech: card.isLeech, delayMs: fuzzedDays * SM2_MS_PER_DAY,
    };
  }

  if (rating === SM2_RATING.GOOD) {
    let candidate = Math.min(maxDays, prevInterval * prevEase * rs.intervalModifier);
    if (candidate <= prevInterval && maxDays > prevInterval) candidate = Math.min(maxDays, prevInterval + 1);
    const { fuzzedDays } = sm2ApplyFuzzDays(candidate, card.id, nowMs, maxDays);
    return {
      newState: SM2_CARD_STATE.REVIEW, newIntervalDays: fuzzedDays, newEase: prevEase, repsCorrectInARow: card.repsCorrectInARow + 1,
      newLapses: card.lapses, newLearningStepIndex: card.learningStepIndex, newRelearningStepIndex: 0,
      dueAt: sm2DayKeyFromNow(nowMs, fuzzedDays), isLeech: card.isLeech, delayMs: fuzzedDays * SM2_MS_PER_DAY,
    };
  }

  const newEase = prevEase + 0.15;
  const candidate = Math.min(maxDays, prevInterval * prevEase * rs.easyBonus * rs.intervalModifier);
  const { fuzzedDays } = sm2ApplyFuzzDays(candidate, card.id, nowMs, maxDays);
  return {
    newState: SM2_CARD_STATE.REVIEW, newIntervalDays: fuzzedDays, newEase, repsCorrectInARow: card.repsCorrectInARow + 1,
    newLapses: card.lapses, newLearningStepIndex: card.learningStepIndex, newRelearningStepIndex: 0,
    dueAt: sm2DayKeyFromNow(nowMs, fuzzedDays), isLeech: card.isLeech, delayMs: fuzzedDays * SM2_MS_PER_DAY,
  };
}

function sm2MinutesWithFuzz(nominalMin, card, settings, nowMs, tag) {
  if (!settings.fuzz.enabled) return nominalMin;
  const { fuzzedMinutes } = sm2ApplyFuzzMinutes(nominalMin, `${card.id}:${tag}`, nowMs, settings.fuzz.learningStepMaxExtraMinutes);
  return fuzzedMinutes;
}
function sm2CrossesDayBoundary(delayMin) { return delayMin >= 1440; }
function sm2DayKeyFromNow(nowMs, days) {
  const d = new Date(nowMs);
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() + days);
  return d.getTime();
}

/* ---------------------------------------------------------------------------
   Compatibility bridge: converts between the OLD simple card shape
   ({ interval, easeFactor, repetitions, dueDate, lastResult }), which every
   existing call site in this file still reads (buildQuestionPool, Insights
   status pills, dashboard due-counters, sidebar counters), and the NEW
   SM-2 card shape ({ state, intervalDays, ease, due, ... }). We store the
   FULL SM-2 shape as the source of truth (under card.sm2), and mirror the
   fields old code expects at the top level so nothing else in the file has
   to change.
   ------------------------------------------------------------------------ */

function sm2ToLegacyShape(sm2Card) {
  const dueDate = sm2Card.due != null ? new Date(sm2Card.due).toISOString() : null;
  return {
    interval: sm2Card.intervalDays,
    easeFactor: sm2Card.ease ?? SM2_DEFAULT_DECK_SETTINGS.review.startingEase,
    repetitions: sm2Card.repsCorrectInARow,
    dueDate,
    lastResult: sm2Card.state !== SM2_CARD_STATE.RELEARNING && sm2Card.lapses === 0 ? true : (sm2Card.reviewLog.length ? sm2Card.reviewLog[sm2Card.reviewLog.length - 1].rating !== SM2_RATING.AGAIN : true),
    sm2: sm2Card,
  };
}

function sm2FromLegacyOrFresh(legacyOrSm2Card, questionId) {
  if (legacyOrSm2Card?.fsrs?.card) {
    const card = legacyOrSm2Card.fsrs.card;
    return {
      id: questionId,
      state: fsrsStateName(card.state),
      intervalDays: Number(card.scheduled_days) || 0,
      ease: null,
      repsCorrectInARow: Number(card.reps) || 0,
      lapses: Number(card.lapses) || 0,
      due: card.due ? new Date(card.due).getTime() : null,
      lastReviewedAt: card.last_review ? new Date(card.last_review).getTime() : null,
      isLeech: false,
      reviewLog: legacyOrSm2Card.fsrs.reviews || [],
    };
  }
  if (legacyOrSm2Card && legacyOrSm2Card.sm2 && legacyOrSm2Card.sm2.state) {
    return legacyOrSm2Card.sm2;
  }
  if (legacyOrSm2Card && legacyOrSm2Card.state) return legacyOrSm2Card;
  return sm2CreateNewCard(questionId);
}

function scheduleCardSM2(storedCard, rating, questionId, deckSettings = SM2_DEFAULT_DECK_SETTINGS, nowMs = Date.now()) {
  const sm2Card = sm2FromLegacyOrFresh(storedCard, questionId);
  const updatedSm2 = sm2ApplyRating(sm2Card, deckSettings, rating, nowMs);
  return sm2ToLegacyShape(updatedSm2);
}

function previewCardSM2(storedCard, rating, questionId, deckSettings = SM2_DEFAULT_DECK_SETTINGS, nowMs = Date.now()) {
  const sm2Card = sm2FromLegacyOrFresh(storedCard, questionId);
  return sm2PreviewRating(sm2Card, deckSettings, rating, nowMs);
}

function isDue(card) {
  if (!card) return true;
  if (card?.fsrs?.card) {
    const due = new Date(card.fsrs.card.due).getTime();
    return Number.isFinite(due) ? due <= Date.now() : true;
  }
  const sm2Card = sm2FromLegacyOrFresh(card, card.id || "unknown");
  if (sm2Card.state === SM2_CARD_STATE.SUSPENDED) return false;
  if (!card.dueDate) return true;
  return new Date(card.dueDate).getTime() <= Date.now();
}

function cardStatus(card) {
  if (!card) return "new";
  if (card?.fsrs?.card) {
    const state = fsrsStateName(card.fsrs.card.state);
    if (state === "learning" || state === "relearning") return state;
    return isDue(card) ? "due" : "learned";
  }
  const sm2Card = card.sm2;
  if (sm2Card) {
    if (sm2Card.state === SM2_CARD_STATE.SUSPENDED) return "suspended";
    if (sm2Card.state === SM2_CARD_STATE.RELEARNING) return "relearning";
    if (sm2Card.state === SM2_CARD_STATE.LEARNING) return "learning";
  }
  if (isDue(card)) return "due";
  return "learned";
}

/* =============================================================================
   SM2AnswerFooter — the four-button Igen/Svær/God/Nem answer area (app-51)
   ---------------------------------------------------------------------------
   Renders once the correct answer + explanation are revealed, replacing the
   plain Previous/Next footer for that moment. Shows live, scheduler-computed
   intervals on every button, handles keyboard shortcuts (1-4, Enter/space),
   defaults to "Igen" when the user picked wrong (without locking self-rating),
   warns before a leech-triggering "Igen", and commits atomically so double
   clicks / retries never double-apply a review.
   ========================================================================== */

const SM2_RATING_ORDER = [
  { key: SM2_RATING.AGAIN, label: "Igen", hint: "Igen = forkert", shortcut: "1", icon: "\u21ba" },
  { key: SM2_RATING.HARD, label: "Svær", hint: "Svær = korrekt med stor tøven", shortcut: "2", icon: "\u2248" },
  { key: SM2_RATING.GOOD, label: "God", hint: "God = korrekt", shortcut: "3", icon: "\u2713" },
  { key: SM2_RATING.EASY, label: "Nem", hint: "Nem = umiddelbart korrekt", shortcut: "4", icon: "\u2713\u2713" },
];

function sm2RatingVisual(c, key) {
  const accent = sm2AccentFor(c, key);
  const tones = {
    [SM2_RATING.AGAIN]: { surface: c.redSoft, label: "Forkert", icon: "↻" },
    [SM2_RATING.HARD]: { surface: c.soft, label: "Tøvende", icon: "≈" },
    [SM2_RATING.GOOD]: { surface: c.greenSoft, label: "Korrekt", icon: "✓" },
    [SM2_RATING.EASY]: { surface: c.blueSoft, label: "Let", icon: "✦" },
  };
  return { ...accent, ...tones[key] };
}

function sm2AccentFor(c, key) {
  switch (key) {
    case SM2_RATING.AGAIN:
      return { border: `2px solid ${c.red}`, iconBg: c.redSoft, iconColor: c.red };
    case SM2_RATING.HARD:
      return { border: `2px dashed ${c.borderStrong}`, iconBg: c.soft, iconColor: c.secondary };
    case SM2_RATING.GOOD:
      return { border: `2px solid ${c.green}`, iconBg: c.greenSoft, iconColor: c.green };
    case SM2_RATING.EASY:
      return { border: `2px solid ${c.blue}`, iconBg: c.blueSoft, iconColor: c.blue };
    default:
      return { border: `1px solid ${c.border}`, iconBg: c.soft, iconColor: c.secondary };
  }
}

function sm2MakeIdempotencyKey(cardId, nowMs) {
  return `${cardId}:${nowMs}:${Math.random().toString(36).slice(2, 8)}`;
}

function SM2AnswerFooter({
  c,
  questionId,
  spacedData,
  setSpacedData,
  wrongChoiceSelected,
  onRated,
}) {
  const [submitting, setSubmitting] = useState(false);
  const [selected, setSelected] = useState(null);
  const [error, setError] = useState(null);
  const [previews, setPreviews] = useState({});
  const [engineState, setEngineState] = useState("loading");
  const inFlightRef = useRef(false);
  const nowMsRef = useRef(Date.now());
  const storedCard = spacedData?.[questionId] || null;
  const suggestedDefault = wrongChoiceSelected ? SM2_RATING.AGAIN : SM2_RATING.GOOD;

  useEffect(() => {
    let cancelled = false;
    nowMsRef.current = Date.now();
    setSelected(null);
    setSubmitting(false);
    setError(null);
    setEngineState("loading");
    inFlightRef.current = false;
    fsrsPreviewOfficial(storedCard, questionId, nowMsRef.current)
      .then((next) => {
        if (cancelled) return;
        setPreviews(next);
        setEngineState("ready");
      })
      .catch((loadError) => {
        if (cancelled) return;
        // Offline fallback preserves the ability to answer, but makes it clear
        // that the official FSRS engine was not available for this review.
        const fallback = {};
        SM2_RATING_ORDER.forEach((entry) => {
          fallback[entry.key] = previewCardSM2(storedCard, entry.key, questionId, SM2_DEFAULT_DECK_SETTINGS, nowMsRef.current);
        });
        setPreviews(fallback);
        setEngineState("fallback");
        setError("Automatisk repetition er midlertidigt offline. Kortet gemmes stadig med en sikker reserveplan.");
      });
    return () => { cancelled = true; };
  }, [questionId, storedCard?.dueDate, storedCard?.fsrs?.updatedAt]);

  useEffect(() => {
    function onKeyDown(event) {
      if (submitting || engineState === "loading") return;
      const map = { "1": SM2_RATING.AGAIN, "2": SM2_RATING.HARD, "3": SM2_RATING.GOOD, "4": SM2_RATING.EASY };
      if (map[event.key] != null) {
        event.preventDefault();
        handleSelect(map[event.key]);
      } else if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        handleSelect(SM2_RATING.GOOD);
      }
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [submitting, engineState, storedCard, questionId]);

  async function handleSelect(rating) {
    if (submitting || inFlightRef.current || engineState === "loading") return;
    inFlightRef.current = true;
    setSubmitting(true);
    setSelected(rating);
    setError(null);
    try {
      const updated = engineState === "ready"
        ? await fsrsApplyOfficial(storedCard, rating, questionId, nowMsRef.current)
        : scheduleCardSM2(storedCard, rating, questionId, SM2_DEFAULT_DECK_SETTINGS, nowMsRef.current);
      const persisted = { ...(spacedData || {}), [questionId]: updated };
      localStorage.setItem(STORAGE.spacedRepetition, JSON.stringify(persisted));
      window.dispatchEvent(new CustomEvent("medlearn-storage-update", { detail: { key: STORAGE.spacedRepetition } }));
      setSpacedData(persisted);
      onRated(updated, rating);
    } catch (saveError) {
      setSubmitting(false);
      setSelected(null);
      inFlightRef.current = false;
      setError("Kunne ikke gemme repetitionen. Prøv igen.");
    }
  }

  return (
    <div className="fsrs-answer-footer" role="group" aria-label="Vurdér dit svar">
      <div className="fsrs-answer-heading">
        <div>
          <strong>Repetition af flashcards</strong>
          <span>{engineState === "ready" ? "Automatisk intervalplan" : engineState === "loading" ? "Indlæser intervalmotor…" : "Kompatibilitetstilstand"}</span>
        </div>
        <span className="fsrs-engine-pill">{engineState === "ready" ? "Automatisk" : engineState === "loading" ? "…" : "Reserve"}</span>
      </div>
      {error && <div className="fsrs-inline-warning" role="status">{error}</div>}
      <div className="fsrs-rating-grid">
        {SM2_RATING_ORDER.map((entry) => {
          const preview = previews[entry.key];
          const isDefault = entry.key === suggestedDefault;
          const isSelected = selected === entry.key;
          return (
            <button
              key={entry.key}
              type="button"
              disabled={submitting || engineState === "loading"}
              onClick={() => handleSelect(entry.key)}
              data-rating={entry.key}
              data-default={isDefault ? "true" : "false"}
              data-selected={isSelected ? "true" : "false"}
              aria-keyshortcuts={entry.shortcut}
            >
              <span className="fsrs-rating-top"><b>{entry.label}</b><kbd>{entry.shortcut}</kbd></span>
              <span className="fsrs-rating-interval">{preview ? sm2FormatIntervalDa(preview.delayMs || 0) : "…"}</span>
              <small>{entry.hint.replace(" = ", ": ")}</small>
            </button>
          );
        })}
      </div>
    </div>
  );
}

function getFullQuestionBank(extraQuestions) {
  return Array.isArray(extraQuestions)
    ? extraQuestions
    : [];
}

function updateLocalizedField(original, language, newValue) {
  const base = original || { da: "", en: "", ar: "" };
  return { ...base, [language]: newValue };
}

function buildFixedBuckets(points, bucketCount) {
  if (!Array.isArray(points) || points.length === 0 || bucketCount <= 0) return [];
  const sorted = [...points].sort((a, b) => (a.time ?? a.date ?? 0) - (b.time ?? b.date ?? 0));
  const first = sorted[0].time ?? sorted[0].date;
  const last = sorted[sorted.length - 1].time ?? sorted[sorted.length - 1].date;
  if (first === undefined || last === undefined || first === last) {
    return sorted.map((p, idx) => ({ ...p, bucketIndex: idx, bucketFraction: sorted.length <= 1 ? 0.5 : idx / (sorted.length - 1) }));
  }
  const span = last - first;
  const buckets = [];
  for (let i = 0; i < bucketCount; i++) {
    const fraction = bucketCount === 1 ? 0.5 : i / (bucketCount - 1);
    const pivot = first + fraction * span;
    let closest = sorted[0];
    let best = Math.abs((closest.time ?? closest.date) - pivot);
    for (let j = 1; j < sorted.length; j++) {
      const t = sorted[j].time ?? sorted[j].date;
      const d = Math.abs(t - pivot);
      if (d < best) {
        best = d;
        closest = sorted[j];
      }
    }
    buckets.push({ ...closest, bucketIndex: i, bucketFraction: fraction });
  }
  return buckets;
}

function formatXAxisLabel(point, range) {
  const value = point.time ?? point.date;
  if (!value) return '';
  const d = new Date(value);
  if (range === '1d') {
    return d.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
  }
  return d.toLocaleDateString();
}

function sm2StartOfTomorrow(nowMs = Date.now()) {
  const tomorrow = new Date(nowMs);
  tomorrow.setHours(24, 0, 0, 0);
  return tomorrow.getTime();
}

function sm2CardDueMs(card) {
  if (!card) return null;
  const sm2 = sm2FromLegacyOrFresh(card, card.id || "unknown");
  return sm2.due ?? (card.dueDate ? new Date(card.dueDate).getTime() : null);
}

// A card remains in the active MCQ session until it is deliberately scheduled
// for tomorrow or later. This is independent from whether a short step is due now.
function sm2IsInTodayQueue(card, nowMs = Date.now()) {
  if (!card) return true;
  const sm2 = sm2FromLegacyOrFresh(card, card.id || "unknown");
  if (sm2.state === SM2_CARD_STATE.SUSPENDED) return false;
  const dueMs = sm2CardDueMs(card);
  return dueMs == null || dueMs < sm2StartOfTomorrow(nowMs);
}

function sm2NextPendingTodayIndex(pool, spacedData, currentIndex, nowMs = Date.now()) {
  return pool
    .map((question, index) => ({ question, index, card: spacedData?.[question.id] }))
    .filter(({ index, card }) => index !== currentIndex && sm2IsInTodayQueue(card, nowMs))
    .sort((a, b) => {
      const aDue = sm2CardDueMs(a.card) ?? nowMs;
      const bDue = sm2CardDueMs(b.card) ?? nowMs;
      return aDue - bDue || a.index - b.index;
    })[0]?.index ?? null;
}

function sm2QueuePriority(card) {
  const state = sm2FromLegacyOrFresh(card, card?.id || "unknown").state;
  if (state === SM2_CARD_STATE.LEARNING || state === SM2_CARD_STATE.RELEARNING) return 0;
  if (state === SM2_CARD_STATE.REVIEW) return 1;
  return 2;
}

function sm2NextDueQuestionIndex(pool, spacedData, answered, currentIndex, nowMs = Date.now()) {
  const due = pool
    .map((question, index) => ({ question, index, card: spacedData?.[question.id] }))
    .filter(({ index, card }) => index !== currentIndex && isDue(card))
    .sort((a, b) => {
      const priority = sm2QueuePriority(a.card) - sm2QueuePriority(b.card);
      if (priority) return priority;
      const aDue = a.card?.sm2?.due ?? (a.card?.dueDate ? new Date(a.card.dueDate).getTime() : 0);
      const bDue = b.card?.sm2?.due ?? (b.card?.dueDate ? new Date(b.card.dueDate).getTime() : 0);
      return aDue - bDue || a.index - b.index;
    });
  if (due.length) return due[0].index;
  const unseen = pool.findIndex((question, index) => index !== currentIndex && answered[question.id] === undefined);
  return unseen >= 0 ? unseen : null;
}

function buildQuestionPool(scope, spacedData, extraQuestions, buried) {
  const allQuestions = getFullQuestionBank(extraQuestions).filter((question) => !(buried && buried[question.id]));
  if (!scope) return allQuestions;
  const { moduleId, groupFilter, lectureFilter, mode, contentType, questionIds } = scope;
  const exactIds = Array.isArray(questionIds) && questionIds.length ? new Set(questionIds) : null;
  let pool = exactIds
    ? allQuestions.filter((question) => exactIds.has(question.id))
    : allQuestions.filter((question) => question.moduleId === moduleId);

  if (!exactIds) {
    if (contentType === "examSet") pool = pool.filter((question) => !question.lectureId);
    else if (contentType === "lectures") pool = pool.filter((question) => Boolean(question.lectureId));

    if (lectureFilter) pool = pool.filter((question) => question.lectureId === lectureFilter);
    else if (groupFilter) {
      const idsInGroup = (MODULE_LECTURES[moduleId] || []).filter((lecture) => lecture.group === groupFilter).map((lecture) => lecture.id);
      pool = pool.filter((question) => idsInGroup.includes(question.lectureId));
    }
    if (!pool.length && !contentType) pool = allQuestions.filter((question) => question.moduleId === moduleId);
  }

  pool = pool.filter((question) => sm2IsInTodayQueue(spacedData[question.id]));
  if (mode === "due" || exactIds) {
    pool = pool.filter((question) => {
      const card = spacedData[question.id];
      if (!card) return false;
      const state = sm2FromLegacyOrFresh(card, question.id).state;
      return state === SM2_CARD_STATE.LEARNING || state === SM2_CARD_STATE.RELEARNING || isDue(card);
    });
  }

  return pool
    .map((question) => ({ question, due: spacedData[question.id]?.dueDate ? new Date(spacedData[question.id].dueDate).getTime() : 0 }))
    .sort((a, b) => sm2QueuePriority(spacedData[a.question.id]) - sm2QueuePriority(spacedData[b.question.id]) || a.due - b.due)
    .map((item) => item.question);
}

const DR_BYTE_STOPWORDS = {
  da: new Set([
    "og","i","jeg","det","at","en","den","til","er","som","på","de","med","han","af","for","ikke","der","var",
    "mig","sig","men","et","har","om","vi","min","havde","ham","hun","nu","over","da","fra","du","ud","sin","dem",
    "os","op","man","hans","hvor","eller","hvad","skal","selv","her","alle","vil","blev","kunne","ind","end",
    "kan","denne","dette","disse","hvilken","hvilket","hvilke","kunne","gerne","være","hvordan","hvorfor","hvornår",
    "spørgsmål","spørgsmåler","spørg","find","findes","viser","vis","vise","noget","nogen","meget","mere","mest",
    // Generic academic/filler words that appear across most medical questions and cause
    // false-positive matches when they are the ONLY overlapping word with the query.
    "funktion","funktioner","betydning","årsag","årsager","effekt","effekter","virkning","virkninger",
    "egenskab","egenskaber","kendetegn","karakteristisk","vigtig","vigtigt","primær","primært","hoved",
    "generelt","overordnet","typisk","typiske","forklar","forklare","forklaring","betyder","angår","gøre","gør",
  ]),
  en: new Set([
    "the","is","at","which","on","a","an","and","or","of","to","in","for","with","that","this","these","those",
    "what","which","who","whom","how","why","when","where","find","show","tell","question","questions","about",
    "can","could","would","should","do","does","did","are","was","were","be","been","being","it","its","as","by",
    "function","functions","meaning","cause","causes","effect","effects","property","properties","feature",
    "characteristic","important","primary","main","general","overall","typical","explain","explains","explanation",
    "does","mean","regarding","concerning",
  ]),
  ar: new Set(["في","من","على","عن","إلى","هل","ما","ماذا","كيف","لماذا","الذي","التي","هذا","هذه","و","أو"]),
};

function stemWord(word) {
  // Lightweight Danish/English suffix stripping so inflected forms match their root.
  return word
    .replace(/(erne|ernes|ene|enes|erens|ernes)$/i, "")
    .replace(/(erne|ende|else|elser)$/i, "")
    .replace(/(erens|ers|end|ing|ede|et|es|er|en|e|s)$/i, (m) => (word.length - m.length >= 3 ? "" : m));
}

function levenshtein(a, b) {
  if (a === b) return 0;
  const al = a.length;
  const bl = b.length;
  if (al === 0) return bl;
  if (bl === 0) return al;
  if (Math.abs(al - bl) > 2) return 99;
  const matrix = Array.from({ length: al + 1 }, (_, i) => [i, ...new Array(bl).fill(0)]);
  for (let j = 0; j <= bl; j++) matrix[0][j] = j;
  for (let i = 1; i <= al; i++) {
    for (let j = 1; j <= bl; j++) {
      matrix[i][j] =
        a[i - 1] === b[j - 1]
          ? matrix[i - 1][j - 1]
          : Math.min(matrix[i - 1][j - 1] + 1, matrix[i][j - 1] + 1, matrix[i - 1][j] + 1);
    }
  }
  return matrix[al][bl];
}

function tokenizeForMatch(text, language) {
  const stopwords = DR_BYTE_STOPWORDS[language] || DR_BYTE_STOPWORDS.da;
  return (text || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, (mark) => mark)
    .normalize("NFC")
    .replace(/[^a-z0-9æøåäöüéèáàíìóòúù\s-]/gi, " ")
    .split(/\s+/)
    .map((word) => word.trim())
    .filter((word) => word.length > 1 && !stopwords.has(word))
    .map((word) => stemWord(word));
}

function wordsAreRelated(queryWord, tokenWord) {
  if (queryWord === tokenWord) return 1;
  if (tokenWord.includes(queryWord) || queryWord.includes(tokenWord)) {
    const shorter = Math.min(queryWord.length, tokenWord.length);
    return shorter >= 3 ? 0.75 : 0;
  }
  if (queryWord.length >= 4 && tokenWord.length >= 4) {
    const distance = levenshtein(queryWord, tokenWord);
    if (distance === 1) return 0.6;
    if (distance === 2 && Math.min(queryWord.length, tokenWord.length) >= 6) return 0.35;
  }
  return 0;
}

function scoreQuestionMatch(query, question, language) {
  const queryWords = tokenizeForMatch(query, language);
  if (queryWords.length === 0) return 0;

  const questionText = translate(question.question, language);
  const categoryText = translate(question.category, language);
  const explanationText = translate(question.explanation, language);
  const optionsText = (question.options || []).map((option) => translate(option, language)).join(" ");

  const haystacks = [
    { tokens: tokenizeForMatch(questionText, language), weight: 3.2 },
    { tokens: tokenizeForMatch(categoryText, language), weight: 2.6 },
    { tokens: tokenizeForMatch(optionsText, language), weight: 1.2 },
    { tokens: tokenizeForMatch(explanationText, language), weight: 1 },
  ];

  // Rare, long, specific technical terms (e.g. "oculomotorius") are far more informative
  // than short common words, even if they only appear once. Boost matches on longer words.
  function specificityBonus(word) {
    if (word.length >= 10) return 2.2;
    if (word.length >= 7) return 1.5;
    return 1;
  }

  let score = 0;
  let uniqueQueryWordsMatched = 0;

  queryWords.forEach((queryWord) => {
    let bestForThisWord = 0;
    haystacks.forEach(({ tokens, weight }) => {
      tokens.forEach((token) => {
        const relatedness = wordsAreRelated(queryWord, token);
        if (relatedness > 0) {
          score += relatedness * weight * specificityBonus(queryWord);
          bestForThisWord = Math.max(bestForThisWord, relatedness);
        }
      });
    });
    if (bestForThisWord > 0) uniqueQueryWordsMatched += 1;
  });

  // Reward questions that cover a larger share of the distinct query words,
  // so a question matching 4/4 words ranks above one matching 1/4 with a rare-word spike.
  const coverageRatio = uniqueQueryWordsMatched / queryWords.length;
  score *= 0.5 + 0.5 * coverageRatio;

  return score;
}

function findMatchingQuestions(query, questionBank, language, limit = 5) {
  // Absolute confidence ceiling: a score above this is treated as a "perfect" match (100%).
  // This is calibrated against typical scores for a well-matched question (weight 3.2 haystack,
  // multiple word hits), not relative to other results in this specific search.
  const ABSOLUTE_CONFIDENCE_CEILING = 6;
  // Minimum absolute score required before we consider a match usable at all.
  const MIN_USABLE_SCORE = 1.2;

  const scored = questionBank
    .map((question) => ({ question, score: scoreQuestionMatch(query, question, language) }))
    .filter((item) => item.score >= MIN_USABLE_SCORE)
    .sort((a, b) => b.score - a.score);

  return scored.slice(0, limit).map((item) => ({
    ...item,
    matchPercent: Math.min(100, Math.round((item.score / ABSOLUTE_CONFIDENCE_CEILING) * 100)),
  }));
}

const DR_BYTE_DIRECT_ANSWER_COPY = {
  da: {
    lowConfidence:
      "Jeg er ikke helt sikker på, at jeg har fundet det rigtige spørgsmål til dette, men her er det mest relevante, jeg kunne finde:",
    answerLabel: "Svar",
    basedOn: "Baseret på spørgsmålet",
  },
  en: {
    lowConfidence:
      "I'm not fully confident this is the right question for this, but here is the most relevant one I could find:",
    answerLabel: "Answer",
    basedOn: "Based on the question",
  },
  ar: {
    lowConfidence: "لست متأكدًا تمامًا من أن هذا هو السؤال الصحيح، لكن هذا هو الأقرب صلة الذي وجدته:",
    answerLabel: "الإجابة",
    basedOn: "بناءً على السؤال",
  },
};

function buildDirectAnswer(matches, language) {
  if (!matches.length) return null;
  const copy = DR_BYTE_DIRECT_ANSWER_COPY[language] || DR_BYTE_DIRECT_ANSWER_COPY.da;
  const top = matches[0];
  const question = top.question;
  const correctOption = (question.options || [])[question.correct];
  const correctLetter = String.fromCharCode(65 + question.correct);
  const explanation = translate(question.explanation, language);
  const isLowConfidence = top.matchPercent < 65;

  const lines = [];
  if (isLowConfidence) lines.push(copy.lowConfidence, "");
  lines.push(`${copy.answerLabel}: ${correctLetter}. ${translate(correctOption, language)}`);
  if (explanation) {
    lines.push("");
    lines.push(explanation);
  }

  return {
    text: lines.join("\n"),
    primaryMatch: top,
    isLowConfidence,
  };
}

function buildAiContextBlock(matches, language) {
  return matches
    .map(({ question }, index) => {
      const optionLines = (question.options || [])
        .map((option, optionIndex) => `${String.fromCharCode(65 + optionIndex)}. ${translate(option, language)}`)
        .join("\n");
      return [
        `[Spørgsmål ${index + 1}] (id: ${question.id})`,
        `Kategori: ${translate(question.category, language)}`,
        `Spørgsmål: ${translate(question.question, language)}`,
        `Svarmuligheder:\n${optionLines}`,
        `Korrekt svar: ${String.fromCharCode(65 + question.correct)}. ${translate((question.options || [])[question.correct], language)}`,
        `Forklaring: ${translate(question.explanation, language)}`,
      ].join("\n");
    })
    .join("\n\n---\n\n");
}

