async function updateFlagStatus(
  flagId,
  nextStatus
) {
  if (flagActionId) return;

  const isDismiss =
    nextStatus === "dismissed";

  const selectedFlag =
  flagged.find(
    (item) => item.id === flagId
  );

  const confirmed = window.confirm(
    isDismiss
      ? language === "en"
        ? "Dismiss this flag?"
        : language === "ar"
          ? "هل تريد رفض هذا البلاغ؟"
          : "Vil du afvise dette flag?"
      : language === "en"
        ? "Mark this flag as resolved?"
        : language === "ar"
          ? "هل تريد تحديد هذا البلاغ كمحلول؟"
          : "Vil du markere dette flag som løst?"
  );

  if (!confirmed) return;

  setFlagActionId(flagId);
  setFlagActionError("");

  try {
    const { data, error } =
      await supabase.rpc(
        "admin_update_question_flag",
        {
          p_flag_id: flagId,
          p_status: nextStatus,
          p_resolution_note: null,
        }
      );

    if (error) {
      throw error;
    }

    const updatedFlag =
      Array.isArray(data) && data.length > 0
        ? data[0]
        : null;

    setFlagged((previous) =>
      previous.map((item) =>
        item.id === flagId
          ? {
              ...item,
              status:
                updatedFlag?.status ||
                nextStatus,
              resolutionNote:
                updatedFlag?.resolution_note ||
                "",
            }
          : item
      )
    );

  await recordAdminActivity({
  action: isDismiss
    ? "flag_dismissed"
    : "flag_resolved",
  entityType: "flag",
  entityId: flagId,
  title:
    selectedFlag?.questionText ||
    selectedFlag?.questionId ||
    flagId,
  moduleId: null,
  lectureId: null,
  details: {
    questionId:
      selectedFlag?.questionId ||
      null,
    nextStatus,
  },
});

setDashboardRefreshKey(
  (value) => value + 1
);
    
  } catch (error) {
    console.error(
      "Kunne ikke opdatere flag:",
      error
    );

    setFlagActionError(
      error?.message ||
        (language === "en"
          ? "The flag could not be updated."
          : language === "ar"
            ? "تعذر تحديث البلاغ."
            : "Flaget kunne ikke opdateres.")
    );
  } finally {
    setFlagActionId(null);
  }
}

